import numpy as np
import math
from numba import njit

_PI = math.pi


@njit
def _energy(p, side):
    total = 0.0
    for i in range(len(p)):
        a = p[i, 2]
        c, s = math.cos(a), math.sin(a)
        h = 0.5 * (abs(c) + abs(s))
        for z in (h-p[i, 0], h-p[i, 1],
                  p[i, 0]+h-side, p[i, 1]+h-side):
            if z > 0.0:
                total += 6.0*z*z
        for j in range(i):
            b = p[j, 2]
            cb, sb = math.cos(b), math.sin(b)
            dx = p[i, 0]-p[j, 0]
            dy = p[i, 1]-p[j, 1]
            r = 0.5*(1.0+abs(math.cos(a-b))+abs(math.sin(a-b)))
            z = min(r-abs(dx*c+dy*s), r-abs(-dx*s+dy*c),
                    r-abs(dx*cb+dy*sb), r-abs(-dx*sb+dy*cb))
            if z > 0.0:
                total += z*z
    return total


def _rotation(a):
    c, s = math.cos(a), math.sin(a)
    return np.array([[c, s], [-s, c]])


def _symmetry(p, side, rng):
    q = p.copy()
    for _ in range(int(rng.integers(4))):
        x = q[:, 0].copy()
        q[:, 0] = side-q[:, 1]
        q[:, 1] = x
        q[:, 2] += _PI/2
    if rng.random() < 0.5:
        q[:, 0] = side-q[:, 0]
        q[:, 2] = _PI-q[:, 2]
    q[:, 2] %= _PI/2
    return q


def _patch(size, angle, center, rng):
    # A connected polyomino in a unit lattice; size >= 3 is branched.
    sites = [(0, 0), (1, 0)]
    if size >= 3:
        sites.append((0, 1 if rng.random() < 0.5 else -1))
    while len(sites) < size:
        if rng.random() < 0.65:
            candidates = [(max(x for x, y in sites)+1, 0)]
        else:
            candidates = []
            for x, y in sites:
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    t = (x+dx, y+dy)
                    if t not in sites and abs(t[1]) <= 1:
                        candidates.append(t)
        t = candidates[int(rng.integers(len(candidates)))]
        if t not in sites:
            sites.append(t)
    uv = np.asarray(sites[:size], dtype=float)
    uv -= uv.mean(axis=0)
    xy = uv @ _rotation(angle) + center
    return np.column_stack((xy, np.full(size, angle)))


def _row_site(bank, row, length, side):
    x, y = 0.5+length, side-0.5-row
    if bank == 1:
        x, y = side-x, side-y
    return np.array([x, y, 0.0])


def _fresh(side, rng):
    total = int(rng.integers(9, 18))
    domains = int(rng.integers(2, 5))
    sizes = np.full(domains, total//domains, dtype=int)
    sizes[:total % domains] += 1
    lengths = np.tile(np.arange(7, 0, -1), (2, 1))
    # Remove staircase end sites, rather than scattering vacancies.
    while lengths.sum() > 65-total:
        weights = np.where(lengths > 0, np.arange(1, 8)[None, :], 0)
        flat = weights.ravel().astype(float)
        j = int(rng.choice(14, p=flat/flat.sum()))
        lengths.ravel()[j] -= 1
    pieces, labels = [], []
    for bank in range(2):
        for row in range(7):
            m = int(lengths[bank, row])
            if m:
                q = np.array([_row_site(bank, row, i, side)
                              for i in range(m)])
                pieces.append(q)
                labels.extend([7*bank+row]*m)
    pieces.append(np.array([[0.5, 0.5, 0.0],
                            [side-0.5, side-0.5, 0.0]]))
    labels.extend([-1, -1])
    cursor = 0
    for j, size in enumerate(sizes):
        t = (cursor+0.5*size)/total
        center = np.full(2, 1.3+(side-2.6)*t)
        center += rng.uniform(-0.25, 0.25, 2)
        angle = rng.uniform(26, 42)*_PI/180
        if rng.random() < 0.5:
            angle = _PI/2-angle
        pieces.append(_patch(int(size), angle, center, rng))
        labels.extend([14+j]*int(size))
        cursor += size
    return np.vstack(pieces), np.asarray(labels, dtype=int)


def _components(p, ids):
    remaining = set(int(i) for i in ids)
    groups = []
    while remaining:
        first = min(remaining)
        remaining.remove(first)
        group, todo = [first], [first]
        while todo:
            i = todo.pop()
            for j in sorted(remaining):
                da = abs((p[i, 2]-p[j, 2]+_PI/4) % (_PI/2)-_PI/4)
                if da < 0.09 and np.linalg.norm(p[i, :2]-p[j, :2]) < 1.55:
                    remaining.remove(j)
                    group.append(j)
                    todo.append(j)
        groups.append(np.asarray(group, dtype=int))
    return groups


def _from_parent(poses, old_side, side, rng):
    p = np.asarray(poses, dtype=float).copy()
    p[:, :2] *= side/old_side
    a = (p[:, 2]+_PI/4) % (_PI/2)-_PI/4
    tilted = np.flatnonzero(np.abs(a) > 0.08)
    if not 6 <= len(tilted) <= 25:
        return _fresh(side, rng)
    labels = np.full(67, -1, dtype=int)
    for i in np.flatnonzero(np.abs(a) <= 0.08):
        x, y = p[i, :2]
        if (x < 1.1 and y < 1.1) or (x > side-1.1 and y > side-1.1):
            continue
        bank = int(y < x)
        yy = y if bank == 0 else side-y
        row = int(np.clip(round(side-0.5-yy), 0, 6))
        labels[i] = bank*7+row
    groups = []
    for ids in _components(p, tilted):
        order = ids[np.argsort(p[ids, 0]+p[ids, 1])]
        groups.extend(np.array_split(order, max(1, int(math.ceil(len(ids)/5)))))
    for j, ids in enumerate(groups):
        labels[ids] = 14+j
    # Rewire one whole patch, with no reliance on a preserved strip.
    eligible = [ids for ids in groups if len(ids) >= 3]
    if not eligible:
        return _fresh(side, rng)
    ids = eligible[int(rng.integers(len(eligible)))]
    center = p[ids, :2].mean(axis=0)
    angle = rng.uniform(25, 41)*_PI/180
    if rng.random() < 0.5:
        angle = _PI/2-angle
    p[ids] = _patch(len(ids), angle, center, rng)
    return p, labels


def _frontier(p, ids, rng):
    # Existing domain orientation defines candidate unit-lattice neighbors.
    a = float(p[ids[0], 2])
    basis = _rotation(a)
    choices = []
    for i in ids:
        for uv in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            xy = p[i, :2] + np.asarray(uv) @ basis
            if np.min(np.sum((p[ids, :2]-xy)**2, axis=1)) > 0.25:
                choices.append(np.r_[xy, a])
    if not choices:
        return None
    return choices[int(rng.integers(len(choices)))].copy()


def _append_row(p, labels, index, row, side):
    ids = np.flatnonzero(labels == row)
    bank, level = divmod(int(row), 7)
    if len(ids):
        coords = p[ids, 0] if bank == 0 else side-p[ids, 0]
        end = ids[int(np.argmax(coords))]
        q = p[end].copy()
        q[0] += 1.0 if bank == 0 else -1.0
        q[2] = 0.0
    else:
        q = _row_site(bank, level, 0, side)
    p[index] = q
    labels[index] = row


def _search(state, side, rng):
    p, labels = state
    p, labels = p.copy(), labels.copy()
    value = float(_energy(p, side))
    best, best_value = p.copy(), value
    temperature = max(0.0002, min(0.015, value/60))
    # Exactly 192 construction scores, including the initial score.
    for step in range(191):
        q, lab = p.copy(), labels.copy()
        domains = np.unique(lab[lab >= 14])
        rows = np.unique(lab[(lab >= 0) & (lab < 14)])
        move = int(rng.integers(6))
        if move < 2 and len(domains):
            g = int(rng.choice(domains))
            ids = np.flatnonzero(lab == g)
            if move == 0:
                q[ids, :2] += rng.normal(0, 0.12, 2)
            else:
                turn = rng.normal(0, 3)*_PI/180
                center = q[ids, :2].mean(axis=0)
                q[ids, :2] = (q[ids, :2]-center) @ _rotation(turn)+center
                q[ids, 2] += turn
        elif move == 2 and len(rows):
            ids = np.flatnonzero(lab == int(rng.choice(rows)))
            q[ids, :2] += rng.normal(0, 0.08, 2)
        elif move == 3 and len(rows):
            source = int(rng.choice(rows))
            ids = np.flatnonzero(lab == source)
            bank = source//7
            xx = q[ids, 0] if bank == 0 else side-q[ids, 0]
            index = ids[int(np.argmax(xx))]
            destinations = [r for r in range(14)
                            if r != source and np.sum(lab == r) < 8]
            if destinations:
                _append_row(q, lab, index, int(rng.choice(destinations)), side)
        elif move == 4 and len(domains):
            g = int(rng.choice(domains))
            ids = np.flatnonzero(lab == g)
            if len(ids) > 2:
                index = int(rng.choice(ids))
                retained = ids[ids != index]
                site = _frontier(q, retained, rng)
                if site is not None:
                    q[index] = site
        elif move == 5 and len(domains) and len(rows):
            g = int(rng.choice(domains))
            ids = np.flatnonzero(lab == g)
            if rng.random() < 0.5 and np.sum(lab >= 14) < 23:
                source = int(rng.choice(rows))
                rr = np.flatnonzero(lab == source)
                xx = q[rr, 0] if source < 7 else side-q[rr, 0]
                index = rr[int(np.argmax(xx))]
                site = _frontier(q, ids, rng)
                if site is not None:
                    q[index], lab[index] = site, g
            elif len(ids) > 2 and np.sum(lab >= 14) > 7:
                destinations = [r for r in range(14) if np.sum(lab == r) < 8]
                if destinations:
                    index = int(rng.choice(ids))
                    _append_row(q, lab, index, int(rng.choice(destinations)), side)
        score = float(_energy(q, side))
        if score < best_value:
            best, best_value = q.copy(), score
        temp = temperature*(0.025**(step/190))
        if score <= value or rng.random() < math.exp(-min(700, (score-value)/temp)):
            p, labels, value = q, lab, score
    best[:, 2] %= _PI/2
    return best


def initialize(record, neighbours, rng, count):
    if len(record[0]) != 67:
        raise ValueError('This strategy targets n=67')
    out = []
    for _ in range(max(0, int(count))):
        side = float(record[1])-rng.uniform(0.001, 0.035)
        p = _search(_fresh(side, rng), side, rng)
        out.append((_symmetry(p, side, rng), float(side)))
    return out


def vary(parents, rng, count):
    if not parents or any(len(p) != 67 for p, s in parents):
        raise ValueError('Expected a nonempty n=67 population')
    anchor = min(float(s) for p, s in parents)
    out = []
    for k in range(max(0, int(count))):
        poses, old_side = parents[int(rng.integers(len(parents)))]
        side = anchor-rng.uniform(0.001, 0.035)
        state = (_fresh(side, rng) if k % 4 == 0 else
                 _from_parent(poses, float(old_side), side, rng))
        p = _search(state, side, rng)
        out.append((_symmetry(p, side, rng), float(side)))
    return out
